import{_ as a,a as o,c as n,ac as t}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"第一册：英语初阶 · 全册易错点 · 第54–79课","description":"逐课检查常见错误、适用边界和正确表达。","frontmatter":{"title":"第一册：英语初阶 · 全册易错点 · 第54–79课","description":"逐课检查常见错误、适用边界和正确表达。","splitFrom":"life/english/new-concept/book-1/mistakes.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 全册易错点","summary":"逐课检查常见错误、适用边界和正确表达。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 全册易错点 · 第27–53课","link":"/life/english/new-concept/book-1/mistakes-part-02"},"next":{"text":"第一册：英语初阶 · 全册易错点 · 第80–105课","link":"/life/english/new-concept/book-1/mistakes-part-04"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 全册易错点 · 第27–53课","link":"/life/english/new-concept/book-1/mistakes-part-02"},"next":{"text":"第一册：英语初阶 · 全册易错点 · 第80–105课","link":"/life/english/new-concept/book-1/mistakes-part-04"}},"headers":[],"relativePath":"life/english/new-concept/book-1/mistakes-part-03.md","filePath":"life/english/new-concept/book-1/mistakes-part-03.md"}'),i={name:"life/english/new-concept/book-1/mistakes-part-03.md"};function s(r,e,l,h,p,d){return o(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="第一册-英语初阶-·-全册易错点-·-第54–79课" tabindex="-1">第一册：英语初阶 · 全册易错点 · 第54–79课 <a class="header-anchor" href="#第一册-英语初阶-·-全册易错点-·-第54–79课" aria-label="Permalink to &quot;第一册：英语初阶 · 全册易错点 · 第54–79课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/mistakes">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><h2 id="l54-·-频率副词与天气动词" tabindex="-1">L54 · 频率副词与天气动词 <a class="header-anchor" href="#l54-·-频率副词与天气动词" aria-label="Permalink to &quot;L54 · 频率副词与天气动词 {#l54-·-频率副词与天气动词}&quot;">​</a></h2><p>often 在 be 后、普通动词前是常见位置；不要机械认为所有副词都放句尾。</p><p><strong>对照例句：</strong> The evenings are usually cool in autumn.</p><p>The evenings 是复数主语，are 后放 usually，cool 作表语；in autumn 表季节。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-054">回看讲解和练习</a></p><h2 id="l55-·-一般现在时的习惯动作" tabindex="-1">L55 · 一般现在时的习惯动作 <a class="header-anchor" href="#l55-·-一般现在时的习惯动作" aria-label="Permalink to &quot;L55 · 一般现在时的习惯动作 {#l55-·-一般现在时的习惯动作}&quot;">​</a></h2><p>单数 father 对应 leaves，不能因为句中有 my 就用第一人称形式。</p><p><strong>对照例句：</strong> My father leaves home at half past seven.</p><p>My father 为第三人称单数，所以用 leaves；home 在 leave home 中表示离开家，at half past seven 表钟点。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-055">回看讲解和练习</a></p><h2 id="l56-·-一般现在时的习惯动作" tabindex="-1">L56 · 一般现在时的习惯动作 <a class="header-anchor" href="#l56-·-一般现在时的习惯动作" aria-label="Permalink to &quot;L56 · 一般现在时的习惯动作 {#l56-·-一般现在时的习惯动作}&quot;">​</a></h2><p>单数 father 对应 leaves，不能因为句中有 my 就用第一人称形式。</p><p><strong>对照例句：</strong> We usually cook dinner together.</p><p>We 为复数主语，cook 用原形；usually 放在实义动词前，together 表示一起完成动作。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-056">回看讲解和练习</a></p><h2 id="l57-·-一般现在时与现在进行时" tabindex="-1">L57 · 一般现在时与现在进行时 <a class="header-anchor" href="#l57-·-一般现在时与现在进行时" aria-label="Permalink to &quot;L57 · 一般现在时与现在进行时 {#l57-·-一般现在时与现在进行时}&quot;">​</a></h2><p>不要写 usually am cycling 来表达普通习惯；先区分稳定规律与临时活动。</p><p><strong>对照例句：</strong> I usually cycle to work, but today I am taking the bus.</p><p>Usually cycle 说明惯常出行；but 连接对比，today I am taking the bus 描述今天的临时安排或进行中的出行。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-057">回看讲解和练习</a></p><h2 id="l58-·-一般现在时与现在进行时" tabindex="-1">L58 · 一般现在时与现在进行时 <a class="header-anchor" href="#l58-·-一般现在时与现在进行时" aria-label="Permalink to &quot;L58 · 一般现在时与现在进行时 {#l58-·-一般现在时与现在进行时}&quot;">​</a></h2><p>不要写 usually am cycling 来表达普通习惯；先区分稳定规律与临时活动。</p><p><strong>对照例句：</strong> Leo is wearing a suit now.</p><p>Leo 是单数主语，is wearing 描述此刻穿着；wear 表穿着状态，a suit 为宾语，now 给出当前时间。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-058">回看讲解和练习</a></p><h2 id="l59-·-可数和不可数名词的数量" tabindex="-1">L59 · 可数和不可数名词的数量 <a class="header-anchor" href="#l59-·-可数和不可数名词的数量" aria-label="Permalink to &quot;L59 · 可数和不可数名词的数量 {#l59-·-可数和不可数名词的数量}&quot;">​</a></h2><p>flour 为不可数名词，问多少用 much；envelopes 用 many。</p><p><strong>对照例句：</strong> We need five envelopes and some writing paper.</p><p>Need 的宾语由 five envelopes 和 some writing paper 并列组成：前者可数复数，后者不可数。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-059">回看讲解和练习</a></p><h2 id="l60-·-可数和不可数名词的数量" tabindex="-1">L60 · 可数和不可数名词的数量 <a class="header-anchor" href="#l60-·-可数和不可数名词的数量" aria-label="Permalink to &quot;L60 · 可数和不可数名词的数量 {#l60-·-可数和不可数名词的数量}&quot;">​</a></h2><p>flour 为不可数名词，问多少用 much；envelopes 用 many。</p><p><strong>对照例句：</strong> How much flour do you need?</p><p>How much flour 是疑问宾语，flour 不可数；do 放在主语 you 之前，need 用原形。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-060">回看讲解和练习</a></p><h2 id="l61-·-have-表身体状况与-must" tabindex="-1">L61 · have 表身体状况与 must <a class="header-anchor" href="#l61-·-have-表身体状况与-must" aria-label="Permalink to &quot;L61 · have 表身体状况与 must {#l61-·-have-表身体状况与-must}&quot;">​</a></h2><p>不要把 has a headache 写成 is a headache；with 后用 him 而非 he。</p><p><strong>对照例句：</strong> Mina has a headache today.</p><p>Mina 是第三人称单数，have 变 has；a headache 是表示身体状况的名词短语，today 表时间。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-061">回看讲解和练习</a></p><h2 id="l62-·-have-表身体状况与-must" tabindex="-1">L62 · have 表身体状况与 must <a class="header-anchor" href="#l62-·-have-表身体状况与-must" aria-label="Permalink to &quot;L62 · have 表身体状况与 must {#l62-·-have-表身体状况与-must}&quot;">​</a></h2><p>不要把 has a headache 写成 is a headache；with 后用 him 而非 he。</p><p><strong>对照例句：</strong> What is the matter with him?</p><p>What is the matter 构成询问状况的固定问句；with him 指明对象，him 是介词后的宾格。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-062">回看讲解和练习</a></p><h2 id="l63-·-must-not-与-do-not-have-to" tabindex="-1">L63 · must not 与 do not have to <a class="header-anchor" href="#l63-·-must-not-与-do-not-have-to" aria-label="Permalink to &quot;L63 · must not 与 do not have to {#l63-·-must-not-与-do-not-have-to}&quot;">​</a></h2><p>mustn&#39;t 不表示“不必”；免除义务应使用 don&#39;t have to。</p><p><strong>对照例句：</strong> You must not make noise in this room.</p><p>Must not 表禁止，make 用原形；noise 常作不可数名词，in this room 限定规则适用的地方。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-063">回看讲解和练习</a></p><h2 id="l64-·-must-not-与-do-not-have-to" tabindex="-1">L64 · must not 与 do not have to <a class="header-anchor" href="#l64-·-must-not-与-do-not-have-to" aria-label="Permalink to &quot;L64 · must not 与 do not have to {#l64-·-must-not-与-do-not-have-to}&quot;">​</a></h2><p>mustn&#39;t 不表示“不必”；免除义务应使用 don&#39;t have to。</p><p><strong>对照例句：</strong> You do not have to wait outside.</p><p>Do not have to 表示没有义务，并非禁止；wait 用原形，outside 为地点副词。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-064">回看讲解和练习</a></p><h2 id="l65-·-时间表达与-can-表许可" tabindex="-1">L65 · 时间表达与 can 表许可 <a class="header-anchor" href="#l65-·-时间表达与-can-表许可" aria-label="Permalink to &quot;L65 · 时间表达与 can 表许可 {#l65-·-时间表达与-can-表许可}&quot;">​</a></h2><p>a quarter to nine 是8:45，不是9:15；by 表最迟期限，at 表时点。</p><p><strong>对照例句：</strong> Can I stay until a quarter past nine?</p><p>Can I 开头询问许可；stay 为原形，until a quarter past nine 表一直待到9:15。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-065">回看讲解和练习</a></p><h2 id="l66-·-时间表达与-can-表许可" tabindex="-1">L66 · 时间表达与 can 表许可 <a class="header-anchor" href="#l66-·-时间表达与-can-表许可" aria-label="Permalink to &quot;L66 · 时间表达与 can 表许可 {#l66-·-时间表达与-can-表许可}&quot;">​</a></h2><p>a quarter to nine 是8:45，不是9:15；by 表最迟期限，at 表时点。</p><p><strong>对照例句：</strong> You must be home by half past ten.</p><p>Must 后接 be 原形；home 表在家，by half past ten 意为最迟10:30，不是必须恰好10:30。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-066">回看讲解和练习</a></p><h2 id="l67-·-be-的过去式-was-were" tabindex="-1">L67 · be 的过去式 was/were <a class="header-anchor" href="#l67-·-be-的过去式-was-were" aria-label="Permalink to &quot;L67 · be 的过去式 was/were {#l67-·-be-的过去式-was-were}&quot;">​</a></h2><p>Was/Were 自己形成问句，不能写 Did you were ...。</p><p><strong>对照例句：</strong> I was at the library last Saturday.</p><p>I 配过去式 was；at the library 表位置，last Saturday 明确已结束的过去，前面不加 on。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-067">回看讲解和练习</a></p><h2 id="l68-·-be-的过去式-was-were" tabindex="-1">L68 · be 的过去式 was/were <a class="header-anchor" href="#l68-·-be-的过去式-was-were" aria-label="Permalink to &quot;L68 · be 的过去式 was/were {#l68-·-be-的过去式-was-were}&quot;">​</a></h2><p>Was/Were 自己形成问句，不能写 Did you were ...。</p><p><strong>对照例句：</strong> Were your friends at the concert yesterday?</p><p>Were 前置构成过去的 be 问句；your friends 为复数，at the concert 表地点或参与场景。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-068">回看讲解和练习</a></p><h2 id="l69-·-过去存在句与时间介词" tabindex="-1">L69 · 过去存在句与时间介词 <a class="header-anchor" href="#l69-·-过去存在句与时间介词" aria-label="Permalink to &quot;L69 · 过去存在句与时间介词 {#l69-·-过去存在句与时间介词}&quot;">​</a></h2><p>具体某天下午用 on Sunday afternoon；不是 in Sunday afternoon。</p><p><strong>对照例句：</strong> There were hundreds of people at the race.</p><p>There were 引出过去存在的人群；hundreds of people 是复数，at the race 表现场。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-069">回看讲解和练习</a></p><h2 id="l70-·-过去存在句与时间介词" tabindex="-1">L70 · 过去存在句与时间介词 <a class="header-anchor" href="#l70-·-过去存在句与时间介词" aria-label="Permalink to &quot;L70 · 过去存在句与时间介词 {#l70-·-过去存在句与时间介词}&quot;">​</a></h2><p>具体某天下午用 on Sunday afternoon；不是 in Sunday afternoon。</p><p><strong>对照例句：</strong> The final was on Sunday afternoon.</p><p>The final 是单数主语，用 was；on Sunday afternoon 是具体某天下午，所以使用 on。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-070">回看讲解和练习</a></p><h2 id="l71-·-一般过去时与-did" tabindex="-1">L71 · 一般过去时与 did <a class="header-anchor" href="#l71-·-一般过去时与-did" aria-label="Permalink to &quot;L71 · 一般过去时与 did {#l71-·-一般过去时与-did}&quot;">​</a></h2><p>did 后使用 finish，不使用 finished；疑问句已有过去标记。</p><p><strong>对照例句：</strong> She called the office twice yesterday.</p><p>She called 是一般过去时肯定句；called 为规则过去式，twice 表次数，yesterday 表过去时间。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-071">回看讲解和练习</a></p><h2 id="l72-·-一般过去时与-did" tabindex="-1">L72 · 一般过去时与 did <a class="header-anchor" href="#l72-·-一般过去时与-did" aria-label="Permalink to &quot;L72 · 一般过去时与 did {#l72-·-一般过去时与-did}&quot;">​</a></h2><p>did 后使用 finish，不使用 finished；疑问句已有过去标记。</p><p><strong>对照例句：</strong> When did you finish the report?</p><p>When 询问完成时间；did 承担过去标记，you 为主语，finish 恢复原形，the report 为宾语。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-072">回看讲解和练习</a></p><h2 id="l73-·-不规则过去式" tabindex="-1">L73 · 不规则过去式 <a class="header-anchor" href="#l73-·-不规则过去式" aria-label="Permalink to &quot;L73 · 不规则过去式 {#l73-·-不规则过去式}&quot;">​</a></h2><p>did 后用 show 而非 showed；went 只放在没有 did 的过去肯定句中。</p><p><strong>对照例句：</strong> We took the wrong bus and went to the harbour.</p><p>Took 与 went 是并列的过去时谓语，分别来自 take 和 go；and 连接两个先后相关的动作。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-073">回看讲解和练习</a></p><h2 id="l74-·-不规则过去式" tabindex="-1">L74 · 不规则过去式 <a class="header-anchor" href="#l74-·-不规则过去式" aria-label="Permalink to &quot;L74 · 不规则过去式 {#l74-·-不规则过去式}&quot;">​</a></h2><p>did 后用 show 而非 showed；went 只放在没有 did 的过去肯定句中。</p><p><strong>对照例句：</strong> Did the guard show you the right road?</p><p>Did 前置询问过去事件，show 恢复原形；you 是接受者，the right road 是被指出的信息。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-074">回看讲解和练习</a></p><h2 id="l75-·-过去时间标记与-buy-bought" tabindex="-1">L75 · 过去时间标记与 buy/bought <a class="header-anchor" href="#l75-·-过去时间标记与-buy-bought" aria-label="Permalink to &quot;L75 · 过去时间标记与 buy/bought {#l75-·-过去时间标记与-buy-bought}&quot;">​</a></h2><p>two weeks ago 前一般不加 in；ago 放在时间长度之后。</p><p><strong>对照例句：</strong> I bought these boots three weeks ago.</p><p>Bought 是 buy 的不规则过去式；these boots 为宾语，three weeks ago 表从现在回溯三周。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-075">回看讲解和练习</a></p><h2 id="l76-·-过去时间标记与-buy-bought" tabindex="-1">L76 · 过去时间标记与 buy/bought <a class="header-anchor" href="#l76-·-过去时间标记与-buy-bought" aria-label="Permalink to &quot;L76 · 过去时间标记与 buy/bought {#l76-·-过去时间标记与-buy-bought}&quot;">​</a></h2><p>two weeks ago 前一般不加 in；ago 放在时间长度之后。</p><p><strong>对照例句：</strong> Did you wear the new shoes yesterday?</p><p>Did 承担过去标记，wear 不用过去式 wore；the new shoes 为宾语，yesterday 指过去一天。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-076">回看讲解和练习</a></p><h2 id="l77-·-时间介词与否定疑问句" tabindex="-1">L77 · 时间介词与否定疑问句 <a class="header-anchor" href="#l77-·-时间介词与否定疑问句" aria-label="Permalink to &quot;L77 · 时间介词与否定疑问句 {#l77-·-时间介词与否定疑问句}&quot;">​</a></h2><p>on Friday morning 而不是 in Friday morning；at 只标钟点，不接整日。</p><p><strong>对照例句：</strong> My appointment is at ten on Thursday.</p><p>My appointment 是主语，is 连接时间表语；at ten 表钟点，on Thursday 表某一天。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-077">回看讲解和练习</a></p><h2 id="l78-·-时间介词与否定疑问句" tabindex="-1">L78 · 时间介词与否定疑问句 <a class="header-anchor" href="#l78-·-时间介词与否定疑问句" aria-label="Permalink to &quot;L78 · 时间介词与否定疑问句 {#l78-·-时间介词与否定疑问句}&quot;">​</a></h2><p>on Friday morning 而不是 in Friday morning；at 只标钟点，不接整日。</p><p><strong>对照例句：</strong> Can you come earlier on Friday?</p><p>Can you 询问是否能够；come 用原形，earlier 是副词比较级，on Friday 交代是哪天。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-078">回看讲解和练习</a></p><h2 id="l79-·-need-与-must" tabindex="-1">L79 · need 与 must <a class="header-anchor" href="#l79-·-need-与-must" aria-label="Permalink to &quot;L79 · need 与 must {#l79-·-need-与-must}&quot;">​</a></h2><p>need to go 与 must go 的结构不同；不要写 must to go。</p><p><strong>对照例句：</strong> We need to buy rice and tomatoes.</p><p>Need 后接不定式 to buy；rice 不可数，tomatoes 是复数可数名词，两者都作 buy 的宾语。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-079">回看讲解和练习</a></p>',133)])])}const g=a(i,[["render",s]]);export{c as __pageData,g as default};
